            this._commandCollection[0].CommandText = "-- retrieve the total revenue generated by services grouped by staff member, appo" +
                "intment and date\r\nWITH ServiceTotals AS\n(\n    \r\nSELECT\n        \r\nsa.AppointmentI" +
                "D,\n       \r\nsa.StaffID,\n        \r\n-- store the representative month as the date " +
                "of the appointment with the day set to 1\r\nDATEFROMPARTS(YEAR(sa.AppointmentStart" +
                "), MONTH(sa.AppointmentStart), 1) AS AppointmentMonth,\n        SUM(s.Price) AS S" +
                "erviceRevenue,\n       \r\nsa.Discounted\n    \r\nFROM ServiceAppointments sa\n    \r\nJO" +
                "IN ServiceAppointmentsServices sas\n        \r\nON sa.AppointmentID = sas.Appointme" +
                "ntID\n    \r\nJOIN Services s\n        \r\nON sas.ServiceID = s.ServiceID\n    \r\nWHERE " +
                "sa.Completed = 1\n  AND sa.Paid = 1  AND sas.DateDeleted IS NULL\r\nGROUP BY\n      " +
                " \r\n sa.AppointmentID,\n        \r\nsa.StaffID,\n        \r\nDATEFROMPARTS(YEAR(sa.Appo" +
                "intmentStart), MONTH(sa.AppointmentStart), 1),\n        \r\nsa.Discounted\n),\r\n-- re" +
                "trieve the total revenue generated by parts, grouped by appointment\r\n\nPartTotals" +
                " AS\n(\n    \r\nSELECT\n        \r\nsasp.AppointmentID,\n        \r\nSUM(p.SellPrice * sas" +
                "p.Quantity) AS PartsRevenue,\n        \r\nSUM(p.BuyPrice * sasp.Quantity) AS PartsC" +
                "ost\n    \r\nFROM ServiceAppointmentsServicesParts sasp\n    \r\nJOIN Parts p\n        " +
                "\r\nON sasp.PartID = p.PartID\n   \r\nJOIN ServiceAppointments sa\r\nON sa.AppointmentI" +
                "D = sasp.AppointmentID\r\nWHERE sa.Completed = 1 AND sa.Paid = 1 AND sa.DateDelete" +
                "d IS NULL AND sasp.DateDeleted IS NULL\r\nGROUP BY\n        \r\nsasp.AppointmentID\n)\n" +
                "\n\r\nSELECT\n   \r\n st.StaffID,\n    \r\nst.AppointmentMonth,\n   \r\n s.Firstname,\n    \r\n" +
                "s.Surname,\r\n-- sum the service revenue and the parts revenue for the current app" +
                "ointment, ensuring no parts and discounts are handled properly\r\nSUM(\n        \r\n(" +
                "\n            \r\nCASE \n                \r\nWHEN st.Discounted = 1\n                  " +
                "  \r\nTHEN (st.ServiceRevenue + ISNULL(pt.PartsRevenue,0)) * 0.9\n                \r" +
                "\nELSE (st.ServiceRevenue + ISNULL(pt.PartsRevenue,0))\n            \r\nEND\n       \r" +
                "\n )\n        - ISNULL(pt.PartsCost,0)\n    ) \r\nAS MonthlyProfit\n\r\nFROM ServiceTota" +
                "ls st\n\r\n-- left join in case no parts are needed for the appointment\r\nLEFT JOIN " +
                "PartTotals pt\n    \r\nON st.AppointmentID = pt.AppointmentID\r\n\n\nJOIN Staff s\n    \r" +
                "\nON st.StaffID = s.StaffID\r\n\n\nGROUP BY\n    \r\nst.StaffID,\n    \r\nst.AppointmentMon" +
                "th,\r\n\ns.Firstname,\n    \r\ns.Surname\r\n\nORDER BY\n    \r\nst.AppointmentMonth;";
